INSERT INTO `tbl_bible_versions` (`id`, `name`, `shortcode`, `description`, `source`, `date`) VALUES
(2, 'King James Version', 'KJV', 'An English translation of the Christian Bible for the Church of England.', 'tbl_KJV.json', '2020-09-01 16:52:12'),
(3, 'The Message Bible', 'MSG', 'Bible in Contemporary Language is a highly idiomatic translation by Eugene H.', 'tbl_MSG.json', '2020-09-01 16:53:10'),
(4, 'New International Version', 'NIV', 'First published in 1978 by Bible scholars using the earliest, highest quality manuscripts available.', 'tbl_NIV.json', '2020-09-01 16:54:33'),
(5, 'New King James Version', 'NKJV', 'English translation of the Bible first published in 1982 by Thomas Nelson.', 'tbl_NKJV.json', '2020-09-01 16:55:51'),
(6, 'Amplified Bible', 'AMP', 'English language translation of the Bible produced jointly by Zondervan and The Lockman Foundation.', 'tbl_AMP.json', '2020-09-01 16:57:33'),
(7, 'New Living Translation', 'NLT', 'A revision of The Living Bible, the project evolved into a new English translation from Hebrew and Greek texts.', 'tbl_NLT.json', '2020-09-01 16:58:23'),
(8, 'New Revised Standard Version', 'NRSV', 'Published in 1989 by the National Council of Churches. It is a revision of the Revised Standard Version.', 'tbl_NRSV.json', '2020-09-01 16:59:08');
INSERT INTO `tbl_books` (`id`, `cat_id`, `b_name`, `b_desc`, `b_title`, `thumbnail`, `url`, `dele`, `dou`, `dmo`, `uti`, `utimo`, `b_type`, `views_count`, `can_download`, `is_free`, `amount`, `book_url`) VALUES
(15, '1', 'YOUR DAILY LIGHT Vol.1', 'Your Daily Light is a devotional with goal to light your world daily with God\'s word. Through these pages, you will find 365 days of illumination, instruction, encouragement and transformation by the word of God. These thoughts will bring you into a rich fellowship with the Holy Spirit and position you for a life with enless streams of miracles as you walk by faith in God\'s word.', 'YOUR DAILY LIGHT Vol.1', 'WhatsApp_Image_2022-03-24_at_14_46_11.jpeg', 'book_1670413955.pdf', '0', '2022-12-07 11:52:35', '2025-05-13 08:46:47', 'admin@admin.com', 'admin@admin.com', 'book', 33, '0', '0', '19.5', ' https://a.co/d/1uIzrj2'),
(16, '1', 'Your Daily Light: 365 devotionals for daily illumination', 'YOUR DAILY LIGHT is a Christian devotional with goal to bring you daily illumination from the word of God for a victorious and a fulfilling life in Christ. With sound scriptural references, it is a collection of short messages for every day, that brings to you God’s word in simplicity for easy understanding and practical application in your life. Through these pages, you will find 365 days of illumination, inspiration, instruction, guidance, strengthening, encouragement, and transformation by the word of God. It shines the light on you so you can know who you are in Christ Jesus. It shines the light on your path so you can ponder your way to a fulfilling life. And it shows you what is yours in Christ Jesus so you can take possession and live God’s plan for your life. This devotional will build your faith and bring you into a richer fellowship with God and experience of His supernatural power as it is accomplishing in the lives of many around the world. In this first volume, emphasis is made on the benefits of God’s word, How to know God\'s voice, how to obtain results through faith and much more.', 'Your Daily Light: 365 devotionals for daily illumination', 'yourdailylight365.jpg', 'book_1745313130.pdf', '0', '2025-04-22 09:12:10', '2025-04-22 09:12:10', 'admin@admin.com', 'admin@admin.com', 'book', 1, '0', '0', '16.9', ' https://a.co/d/1uIzrj2'),
(17, '1', 'Your Daily Light Vol.2: 90 Devotionals for daily illumination', 'Your Daily Light Vol.2: 90 Devotionals for daily illumination is a Christian devotional with goal to bring you daily illumination from the word of God for a victorious and a fulfilling life in Christ. With sound scriptural references, it is a collection of short messages for every day, that brings to you God’s word in simplicity for easy understanding and practical application in your life. Through these pages, you will find 90 days of illumination, inspiration, instruction, guidance, strengthening, encouragement, and transformation by the word of God. This devotional will build your faith and bring you into a richer fellowship with God and an experience of His supernatural power as it is accomplishing in the lives of many around the world. In this edition, emphasis is made on the believer’s authority in Christ, the role of the Holy Spirit in your life, faith that gets results, a practical guide to fasting, and your privileges in Christ. You will also find in this edition, the inspiration for the right mental attitude that will get you set for a great and more fruitful new year.', 'Your Daily Light Vol.2: 90 Devotionals for daily illumination', '61g-o4aWjIL__SL1500_.jpg', 'book_1745313352.pdf', '0', '2025-04-22 09:15:52', '2025-04-22 09:15:52', 'admin@admin.com', 'admin@admin.com', 'book', 0, '0', '0', '10', 'https://a.co/d/heTR3qs'),
(18, '1', 'Your Daily Light Vol.2: 91 devotionals for daily illumination', 'YOUR DAILY LIGHT is a Christian devotional with goal to bring you daily illumination from the word of God for a victorious and a fulfilling life in Christ. With sound scriptural references, it is a collection of short messages for every day, that brings to you God’s word in simplicity for easy understanding and practical application in your life. Through these pages, you will find 91 days of illumination, inspiration, instruction, guidance, strengthening, encouragement, and transformation by the word of God. This devotional will build your faith and bring you into a richer fellowship with God and an experience of His supernatural power as it is accomplishing in the lives of many around the world. In this edition, emphasis is made on the believer’s authority in Christ, the role of the Holy Spirit in your life, faith that gets results, a practical guide to fasting, and your privileges in Christ. You will also find in this edition, the inspiration for the right mental attitude that will get you set for a great and more fruitful new year.', 'Your Daily Light Vol.2: 91 devotionals for daily illumination', 'ydv2.jpg', 'book_1745313475.pdf', '0', '2025-04-22 09:17:55', '2025-04-22 09:17:55', 'admin@admin.com', 'admin@admin.com', 'book', 0, '0', '0', '9.90', 'https://a.co/d/12fnS7H'),
(19, '1', 'Your Daily Light Vol. 2: 92 Devotionals for your daily illumination, Month July, August & September', 'Your Daily Light Vol. 2: 92 Devotionals for your daily illumination, Month July, August & September is a Christian devotional with goal to bring you daily illumination from the word of God for a victorious and a fulfilling life in Christ. With sound scriptural references, it is a collection of short messages for every day, that brings to you God’s word in simplicity for easy understanding and practical application in your life. Through these pages, you will find 92 days of illumination, inspiration, instruction, guidance, strengthening, encouragement, and transformation by the word of God. This devotional will build your faith and bring you into a richer fellowship with God and an experience of His supernatural power as it is accomplishing in the lives of many around the world. In this special edition, discover seven great benefits of God’s word, build on the knowledge of who you are in Christ, be enlightened on the work of angels, understand faith, and learn spiritual principles for greater effectiveness in prayer. You will also understand more about fellowship with God and come into greater intimacy with Him and His power.', 'Your Daily Light Vol. 2: 92 Devotionals for your daily illumination, Month July, August & September', 'ydvJuly.jpg', 'book_1745313643.pdf', '0', '2025-04-22 09:20:43', '2025-04-22 09:20:43', 'admin@admin.com', 'admin@admin.com', 'book', 0, '0', '0', '9.90', 'https://a.co/d/ar1OJL0'),
(20, '1', 'Your Daily Light Vol. 2: 92 Devotionals for your daily illumination, Month October, November, Decemb', 'YOUR DAILY LIGHT Vol. 2 is a Christian devotional with goal to bring you daily illumination from the word of God for a victorious and a fulfilling life in Christ. With sound scriptural references, it is a collection of short messages for every day, that brings to you God’s word in simplicity for easy understanding and practical application in your life. Through these pages, you will find 92 days of illumination, inspiration, instruction, guidance, strengthening, encouragement, and transformation by the word of God. This devotional will build your faith and bring you into a richer fellowship with God and an experience of His supernatural power as it is accomplishing in the lives of many around the world. In this edition, grow in intimacy with God, build on the knowledge of who you are in Christ, understand prevailing faith and rise above the challenges of life with songs of praise. You will also be inspired in hope and learn more about God’s call to you for this present time.', 'Your Daily Light Vol. 2: 92 Devotionals for your daily illumination, Month October, November, December', 'ydlsept.jpg', 'book_1745313756.pdf', '0', '2025-04-22 09:22:35', '2025-04-22 09:48:18', 'admin@admin.com', 'admin@admin.com', 'book', 2, '0', '0', '7.70', ' https://a.co/d/iolloy0');
