INSERT INTO `tbl_inbox` (`id`, `title`, `message`, `date`) VALUES
(118, 'Mobile App Updates On The Way', '<p>We are working on updates to enhance your experience with God\'s word on the App. We apologize for any unexpected irregularities during this time,particularly as we are observing with Android users unable to access the app content over the last four days.</p>', 1744295873),
(119, 'Welcome To Your Daily Light', '<p><span>Mobile App Updates</span></p>', 1744296833),
(120, 'Mobile App Updates On The Way', '<p><span>We are working on updates to enhance your experience with God\'s word on the App. We apologize for any unexpected irregularities during this time,particularly as we are observing with Android users unable to access the app content over the last four days. We are working to fix this. God bless you!❤️</span></p>', 1746945947),
(121, 'Multiple Notification Error', '<p>Dear user of<strong> Your Daily Light app</strong>, we apologize for the multiple notifications over the last days, particularly on <strong>Android devices</strong>. This is an <strong>error</strong> we are fixing.&nbsp;The app should only receive&nbsp;one daily notification, to help you stay up to date with God\'s word. God bless you!</p>', 1754841999),
(122, 'Look To Jesus', '<p>Read the special prophetic word to you this season, a word from Pastor Simon.</p>', 1756043950);
